/**
 * 用 esbuild 把 scripts/tiptap/entry.js 打包成无构建步骤环境可直载的
 * 单文件 IIFE，产物提交进 public/vendor/tiptap/，由 PWA 按需缓存。
 * 运行 `npm run build:tiptap` 重新生成；产物必须随源码一起提交。
 */
const path = require('path');
const fs = require('fs');
const esbuild = require('esbuild');

const ROOT = path.resolve(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'public', 'vendor', 'tiptap');


const HEADER = [
  '/* DumbPad offline Tiptap bundle. Generated by scripts/build-tiptap-bundle.js',
  ' * from the npm dependencies declared in package.json. Do not edit by hand;',
  ' * rebuild with `npm run build:tiptap` after upgrading dependencies. */',
].join('\n');

const MERMAID_HEADER = [
  '/* DumbPad offline Mermaid bundle. Generated by scripts/build-tiptap-bundle.js',
  ' * from the npm mermaid dependency. Do not edit by hand;',
  ' * rebuild with `npm run build:tiptap` after upgrading dependencies. */',
].join('\n');

async function build() {
  fs.mkdirSync(OUT_DIR, { recursive: true });
  await esbuild.build({
    entryPoints: [path.join(__dirname, 'tiptap', 'entry.js')],
    bundle: true,
    format: 'iife',
    globalName: 'DumbPadTiptap',
    target: ['es2020'],
    minify: true,
    sourcemap: false,
    legalComments: 'none',
    banner: { js: HEADER },
    outfile: path.join(OUT_DIR, 'tiptap.bundle.js'),
    logLevel: 'info',
  });
  const { size } = fs.statSync(path.join(OUT_DIR, 'tiptap.bundle.js'));
  console.log(`tiptap.bundle.js written (${(size / 1024).toFixed(1)} KB)`);
}

async function buildMermaid() {
  fs.mkdirSync(OUT_DIR, { recursive: true });
  await esbuild.build({
    entryPoints: [path.join(__dirname, 'tiptap', 'mermaid-entry.js')],
    bundle: true,
    format: 'iife',
    globalName: 'DumbPadMermaid',
    target: ['es2020'],
    minify: true,
    sourcemap: false,
    legalComments: 'none',
    banner: { js: MERMAID_HEADER },
    outfile: path.join(OUT_DIR, 'tiptap-mermaid.bundle.js'),
    logLevel: 'info',
  });
  const { size } = fs.statSync(path.join(OUT_DIR, 'tiptap-mermaid.bundle.js'));
  console.log(`tiptap-mermaid.bundle.js written (${(size / 1024).toFixed(1)} KB)`);
}

build()
  .then(buildMermaid)
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
